    /**
     * Tests getting all Registrations.
     *
     * @return    Collection
     */
    public List<Registration> testGetAll() throws Throwable {
    LOGGER.info( "RegistrationTest:testGetAll() - Retrieving Collection of Registrations:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Registration : " );
    List<Registration> collection  = null;

    try {
        // call the static get method on the RegistrationService
        collection = service.getAllRegistration();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Registration currEntity  = null;
            Iterator<Registration> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getRegistrationId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

